CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT, access_token TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL UNIQUE REFERENCES users(id), name TEXT NOT NULL DEFAULT 'My community', plan TEXT NOT NULL DEFAULT 'scout', subscription_status TEXT NOT NULL DEFAULT 'free', customer_id TEXT UNIQUE, subscription_id TEXT UNIQUE, guild_id TEXT UNIQUE, guild_name TEXT, alert_channel_id TEXT, created_at BIGINT NOT NULL, alerts_enabled INTEGER NOT NULL DEFAULT 1, failure_threshold INTEGER NOT NULL DEFAULT 1, ban_sharing_enabled INTEGER NOT NULL DEFAULT 0, ban_public_name TEXT NOT NULL DEFAULT '');
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, expires_at BIGINT NOT NULL);
CREATE TABLE servers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, game TEXT NOT NULL CHECK(game IN ('asa','ase')), map TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, password TEXT NOT NULL, max_players INTEGER NOT NULL DEFAULT 70, status TEXT NOT NULL DEFAULT 'unknown', players INTEGER NOT NULL DEFAULT 0, latency INTEGER, last_checked BIGINT, created_at BIGINT NOT NULL, cluster TEXT NOT NULL DEFAULT '', maintenance INTEGER NOT NULL DEFAULT 0, player_list TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '', failed_checks INTEGER NOT NULL DEFAULT 0, failed_since BIGINT);
CREATE TABLE schedules (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, name TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('save','broadcast')), message TEXT NOT NULL DEFAULT '', interval_minutes INTEGER NOT NULL, next_run BIGINT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, last_run BIGINT, last_status TEXT, last_detail TEXT,sort_order BIGINT GENERATED ALWAYS AS IDENTITY UNIQUE);
CREATE TABLE activity (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), server_id TEXT, title TEXT NOT NULL, detail TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'info', created_at BIGINT NOT NULL);
CREATE TABLE metrics (server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, players INTEGER NOT NULL, online INTEGER NOT NULL, created_at BIGINT NOT NULL, latency INTEGER);
CREATE TABLE stripe_events (id TEXT PRIMARY KEY, created_at BIGINT NOT NULL);
CREATE TABLE announcement_templates (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,body TEXT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE maintenance_windows (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,server_ids TEXT NOT NULL,days TEXT NOT NULL,start_time TEXT NOT NULL,duration_minutes INTEGER NOT NULL,time_zone TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at BIGINT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,detail TEXT NOT NULL,level TEXT NOT NULL,target TEXT NOT NULL,source_key TEXT UNIQUE,created_at BIGINT NOT NULL,read_at BIGINT);
CREATE TABLE incidents (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,opened_at BIGINT NOT NULL,resolved_at BIGINT,acknowledged_at BIGINT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE schedule_runs (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),schedule_id TEXT NOT NULL REFERENCES schedules(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,started_at BIGINT NOT NULL,finished_at BIGINT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE moderation (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,identifier TEXT NOT NULL,player_name TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,created_at BIGINT NOT NULL, identity_kind TEXT NOT NULL DEFAULT 'game', identity_key TEXT);
CREATE TABLE hosting_connections (server_id TEXT PRIMARY KEY REFERENCES servers(id) ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider TEXT NOT NULL,origin TEXT NOT NULL,remote_id TEXT NOT NULL,api_key TEXT NOT NULL,verified_at BIGINT NOT NULL);
CREATE TABLE ban_directory_reports (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,identity_key TEXT NOT NULL,identity_kind TEXT NOT NULL,active INTEGER NOT NULL,first_reported_at BIGINT NOT NULL,last_updated_at BIGINT NOT NULL,withdrawn_at BIGINT,UNIQUE(server_id,identity_key));
CREATE TABLE workspace_members (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('admin','moderator','viewer')),server_ids TEXT,created_at BIGINT NOT NULL,UNIQUE(workspace_id,user_id));
CREATE TABLE team_invitations (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),discord_user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','moderator','viewer')),server_ids TEXT,token_hash TEXT NOT NULL UNIQUE,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,accepted_at BIGINT,revoked_at BIGINT);
CREATE TABLE session_workspaces (token_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id));
CREATE TABLE staff_audit (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT,server_id TEXT,created_at BIGINT NOT NULL);
CREATE TABLE player_profiles (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),identity_key TEXT NOT NULL,identity_kind TEXT NOT NULL,game TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(workspace_id,identity_key,game));
CREATE TABLE player_observations (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,display_name TEXT NOT NULL,first_seen BIGINT NOT NULL,last_seen BIGINT NOT NULL,last_checked BIGINT NOT NULL,sightings INTEGER NOT NULL,online INTEGER NOT NULL,PRIMARY KEY(profile_id,server_id));
CREATE TABLE player_notes (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,body TEXT NOT NULL,author_id TEXT NOT NULL,author_name TEXT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);

CREATE INDEX idx_servers_workspace ON servers(workspace_id,created_at,id);
CREATE INDEX idx_schedules_workspace ON schedules(workspace_id,sort_order);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX idx_oauth_expiry ON oauth_states(expires_at);
CREATE INDEX idx_activity_workspace ON activity(workspace_id,created_at DESC);
CREATE INDEX idx_metrics_time ON metrics(server_id,created_at) INCLUDE(players,online,latency);
CREATE UNIQUE INDEX idx_one_open_incident ON incidents(server_id) WHERE resolved_at IS NULL;
CREATE INDEX idx_incidents_workspace ON incidents(workspace_id,opened_at DESC);
CREATE INDEX idx_incidents_server ON incidents(server_id,opened_at);
CREATE UNIQUE INDEX idx_one_active_identity_ban ON moderation(server_id,identity_key) WHERE active=1;
CREATE INDEX idx_templates_workspace ON announcement_templates(workspace_id,created_at,id);
CREATE INDEX idx_windows_workspace ON maintenance_windows(workspace_id,created_at,id);
CREATE INDEX idx_hosting_workspace ON hosting_connections(workspace_id,server_id);
CREATE INDEX idx_notifications_workspace ON notifications(workspace_id,created_at DESC);
CREATE INDEX idx_runs_workspace ON schedule_runs(workspace_id,finished_at DESC);
CREATE INDEX idx_moderation_identity ON moderation(workspace_id,identity_key,action,active);
CREATE INDEX idx_moderation_server_identity ON moderation(server_id,identity_key,action,created_at DESC);
CREATE INDEX idx_shared_ban_identity ON ban_directory_reports(identity_key,workspace_id,active);
CREATE INDEX idx_members_user ON workspace_members(user_id,created_at,id);
CREATE INDEX idx_staff_audit ON staff_audit(workspace_id,created_at DESC);
CREATE INDEX idx_profiles_workspace ON player_profiles(workspace_id,game,id);
CREATE INDEX idx_observations_server ON player_observations(server_id,profile_id);
CREATE INDEX idx_player_notes ON player_notes(profile_id,created_at DESC);
CREATE INDEX idx_team_invitations_workspace ON team_invitations(workspace_id,expires_at) WHERE accepted_at IS NULL AND revoked_at IS NULL;
